.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief .ey-stepper>.ey-step{flex:1 1 0!important;min-width:0!important}
.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief .ey-stepper>.ey-line{flex:0 1 16px!important;min-width:4px!important;margin-inline:4px!important}
.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief .ey-step-text{max-width:100%;overflow-wrap:anywhere}
.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief .ey-stepper .ey-step-text strong{font-size:clamp(10px,2cqi,12px)!important;letter-spacing:0!important;white-space:nowrap!important;overflow-wrap:normal!important}
.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief :is(.ey-actions,.mfp-actions){flex-wrap:wrap}
.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief :is(.ey-actions,.mfp-actions)>:is(button,a){max-width:100%;min-width:0;white-space:normal;overflow-wrap:anywhere}
/* Reserve room for authored note rotation instead of clipping its text/shadow. */
.mf-template-sticky-spark-creative-brief.mf-template-sticky-spark-creative-brief .mfp-sticky-spark .note{max-width:calc(100% - 24px);margin-inline:12px!important}

.mf-template-sticky-spark-creative-brief{box-sizing:border-box;width:100%;container-type:inline-size;container-name:mf-sticky-spark-creative-brief;contain:layout style;isolation:isolate}
